architecture.h4_f:
msg = CBOR{v:1, kikokikona, pane_i, hoouna_i}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/lumi/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, kikokikona, pane_i?, thread_id?, ha'i?, ho'ouna_ma}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
uea = CBOR{
  v: 1,
  ciphertext: hex(ct), // ka lōʻihi hoʻololi
  ʻaʻole: hex(12 B),
  mea hoʻouna_pseudo: hex(16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
waho = CBOR{
  kumu_node: hex32,
  target_mea hoʻohana: int64,
  inner_ciphertext: bytes,
  inner_nonce: bytes,
  sent_at: unix_ms
}
hōʻailona = Ed25519-Sign(source_priv, waho)
POST /federation/deliver { envelope: waho, hōʻailona: hex64 }

auth.h1_f:
POST /api/authentication/register
  { inoa inoa, password, x25519_public_key, display_name, kelepona?, leka uila?, avatar_emoji }

Pane 201 Hana ʻia:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token uku:
  { sub: user_id, jti: device_id, type: "access", exp: ano + 15min }
refresh_token uku:
  { sub: user_id, jti: device_id, type: "refresh", exp: i kēia manawa + 30d }

HS256-kaulima me ka huna huna 64-byte o ka node mai .env

auth.h4_f:
register_begin(): hoʻokūkū = rand(32)
                    nā koho = { rp.id, user.id, pubKeyCredParams, luʻi }
                    koho hoʻihoʻi

hoʻopau_kahi (hōʻoia):
  hōʻoia i ka hōʻoia kūʻē iā TPM / Secure Enclave root CA
  hale kūʻai { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR uku uku = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/hōʻoia { nonce }
  → mea hou i hoʻopaʻa inoa ʻia; Ua hoʻi mai nā JWT.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Kiʻi i waho: { type:"m", lumi, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {inoa faila, nui, chunk_size_hint}
            ← {upload_id, chunk_size}
ʻāpana PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
hoʻopau POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL ma ka pau ʻole: 24 hola

files.h4_f:
hōʻole_papa inoa = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "noi/x-mach-binary",
}
inā magic.from_buffer(buf[:1024]) i ka papa inoa ʻole: hoʻihoʻi 415

presence.h1_f:
mea kūʻai: ma ke kī mua → hoʻouna {type:"t", state:"start"}
         ʻaʻole hoʻouna hou aku no 3 mau keʻena ke hoʻololi ʻole ka mokuʻāina
         10 s ma hope o ke kī hope → hoʻouna {type:"t", state:"stop"}
mea hoʻokipa: hoʻokuʻu kaʻa 10 s ma hope o ka "hoʻomaka" hope inā ʻaʻohe "hoʻomaha" i hiki mai

